def parse_duration(text: str) -> float:
    if not text or text[0] != 'P':
        raise ValueError("Duration must start with 'P'")

    text = text[1:]  # Remove 'P'

    # Split by 'T' if present
    if 'T' in text:
        date_part, time_part = text.split('T', 1)
        if not time_part:
            raise ValueError("'T' must be followed by at least one time component")
    else:
        date_part = text
        time_part = ""

    # Parse date part (weeks or days)
    weeks = 0.0
    days = 0.0

    if date_part:
        if 'W' in date_part:
            if 'D' in date_part:
                raise ValueError("Cannot have both weeks and days")
            # Must be P<n>W format
            if not date_part.endswith('W'):
                raise ValueError("Invalid date format")
            week_str = date_part[:-1]
            if not week_str or not is_valid_number(week_str):
                raise ValueError("Invalid week value")
            weeks = float(week_str.replace(',', '.'))
        elif 'D' in date_part:
            # Must be P<n>D format
            if not date_part.endswith('D'):
                raise ValueError("Invalid date format")
            day_str = date_part[:-1]
            if not day_str or not is_valid_number(day_str):
                raise ValueError("Invalid day value")
            days = float(day_str.replace(',', '.'))
        else:
            raise ValueError("Date part must contain 'W' or 'D'")

    # Parse time part (hours, minutes, seconds)
    hours = 0.0
    minutes = 0.0
    seconds = 0.0

    if time_part:
        # Extract components from time_part
        remaining = time_part

        if 'H' in remaining:
            h_idx = remaining.index('H')
            hour_str = remaining[:h_idx]
            if not hour_str or not is_valid_number(hour_str):
                raise ValueError("Invalid hour value")
            hours = float(hour_str.replace(',', '.'))
            remaining = remaining[h_idx+1:]

        if 'M' in remaining:
            m_idx = remaining.index('M')
            min_str = remaining[:m_idx]
            if not min_str or not is_valid_number(min_str):
                raise ValueError("Invalid minute value")
            minutes = float(min_str.replace(',', '.'))
            remaining = remaining[m_idx+1:]

        if 'S' in remaining:
            s_idx = remaining.index('S')
            sec_str = remaining[:s_idx]
            if not sec_str or not is_valid_number(sec_str):
                raise ValueError("Invalid second value")
            seconds = float(sec_str.replace(',', '.'))
            remaining = remaining[s_idx+1:]

        if remaining:
            raise ValueError("Invalid time format")

    # Check that at least one component is present
    if weeks == 0 and days == 0 and hours == 0 and minutes == 0 and seconds == 0:
        raise ValueError("At least one duration component must be present")

    # Convert to seconds
    total = weeks * 7 * 86400 + days * 86400 + hours * 3600 + minutes * 60 + seconds
    return total


